-- Run only in the disposable CRM page fixture, never against customer data.
IF DB_NAME() NOT LIKE 'Prosto_CRM_Page_Test[_]%' THROW 51999,'Disposable database required',1;
DECLARE @a int,@other int,@parent int,@child int,@second int,@item int,@stamp uniqueidentifier=NEWID(),@ver binary(8),@xml xml;
DECLARE @AccountSeed numeric(38,0)=IDENT_CURRENT('dbo.CRM_Accounts');
INSERT CRM_Accounts(Name_AR,AddedUser,Brand_ID) VALUES(N'اختبار صلاحيات دليل العمل',1,1);SET @a=SCOPE_IDENTITY();
INSERT CRM_Accounts(Name_AR,AddedUser,Brand_ID) VALUES(N'اختبار صلاحيات عميل آخر',1,1);SET @other=SCOPE_IDENTITY();
INSERT Customer_Logins(AccountID,Username,PasswordHash,Salt,Iterations,ModifiedBy,SecurityStamp) VALUES(@a,'guide-access-test',CRYPT_GEN_RANDOM(32),CRYPT_GEN_RANDOM(32),210000,1,@stamp);
INSERT CRM_WorkGuide_Categories(Name_AR,Name_EN,AddedUser,Brand_ID) VALUES(N'تصنيف اختبار الصلاحيات','Access test',1,1);SET @parent=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_Categories(Parent_ID,Name_AR,Name_EN,AddedUser,Brand_ID) VALUES(@parent,N'فرع اختبار الصلاحيات','Child access test',1,1);SET @child=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_Categories(Name_AR,Name_EN,AddedUser,Brand_ID) VALUES(N'تصنيف اختبار ثان','Second access test',1,1);SET @second=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_Items(Name_AR,Name_EN,Summary_AR,Summary_EN,File_Url,File_Name,File_Extension,File_Size,AddedUser,Brand_ID) VALUES(N'دليل اختبار الصلاحيات','Access test guide',N'ملخص','Summary','/FileManager/CRMWorkGuide/11111111111111111111111111111111.pdf','test.pdf','.pdf',10,1,1);SET @item=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_ItemCategories(Item_ID,Category_ID,Brand_ID) VALUES(@item,@parent,1),(@item,@child,1),(@item,@second,1);
SET @xml=CONVERT(xml,CONCAT('<grants><grant id="',@parent,'" view="1" download="0"/><grant id="',@second,'" view="0" download="1"/></grants>'));
BEGIN TRY EXEC CRM_Save_WorkGuide_Permissions 2,@a,@xml;THROW 51999,'Owner changed permissions',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51200 THROW;END CATCH;
EXEC CRM_Save_WorkGuide_Permissions 1,@a,@xml;
SELECT @ver=Row_Version FROM CRM_WorkGuide_AccessState WHERE Account_ID=@a;
IF (SELECT COUNT(*) FROM CRM_WorkGuide_Access WHERE Account_ID=@a)<>2 THROW 51999,'Grant count invalid',1;
BEGIN TRY EXEC CRM_Save_WorkGuide_Permissions 1,@a,@xml;THROW 51999,'Stale initial grant accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
DECLARE @invalid xml=CONVERT(xml,CONCAT('<grants><grant id="',@parent,'" view="9" download="0"/></grants>'));
BEGIN TRY EXEC CRM_Save_WorkGuide_Permissions 1,@a,@invalid,@ver;THROW 51999,'Invalid right accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
SET @invalid=CONVERT(xml,CONCAT('<grants><grant id="',@parent,'" view="1" download="0"/><grant id="',@parent,'" view="0" download="1"/></grants>'));
BEGIN TRY EXEC CRM_Save_WorkGuide_Permissions 1,@a,@invalid,@ver;THROW 51999,'Duplicate category accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
IF (SELECT Row_Version FROM CRM_WorkGuide_AccessState WHERE Account_ID=@a)<>@ver THROW 51999,'Failed mutation changed permissions',1;
EXEC Customer_WorkGuide_List @a,@stamp;
EXEC Customer_WorkGuide_List @a,@stamp,@parent;
EXEC Customer_WorkGuide_File @a,@stamp,@item,@parent,'view';
EXEC Customer_WorkGuide_File @a,@stamp,@item,@second,'download';
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@item,@parent,'download';THROW 51999,'Rights aggregated across categories',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@item,@second,'view';THROW 51999,'Download implied view',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@item,@child,'view';THROW 51999,'Parent permission inherited by child',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
BEGIN TRY EXEC Customer_WorkGuide_List @a,@stamp,@child;THROW 51999,'Child listing inherited',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
BEGIN TRY EXEC Customer_WorkGuide_File @other,@stamp,@item,@parent,'view';THROW 51999,'Another customer accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51911 THROW;END CATCH;
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@item,@parent,'invalid';THROW 51999,'Unknown action accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
UPDATE CRM_WorkGuide_Items SET Is_Active=0 WHERE ID=@item;
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@item,@parent,'view';THROW 51999,'Inactive item leaked',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
UPDATE CRM_WorkGuide_Items SET Is_Active=1 WHERE ID=@item;
UPDATE Customer_Logins SET IsActive=0 WHERE AccountID=@a;
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@item,@parent,'view';THROW 51999,'Disabled login accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51911 THROW;END CATCH;
UPDATE Customer_Logins SET IsActive=1 WHERE AccountID=@a;
UPDATE CRM_Accounts SET Is_Active=0 WHERE ID=@a;
BEGIN TRY EXEC Customer_WorkGuide_List @a,@stamp;THROW 51999,'Inactive account accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51911 THROW;END CATCH;
UPDATE CRM_Accounts SET Is_Active=1 WHERE ID=@a;
DECLARE @BadStamp uniqueidentifier=NEWID();
BEGIN TRY EXEC Customer_WorkGuide_File @a,@BadStamp,@item,@parent,'view';THROW 51999,'Stale security stamp accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51911 THROW;END CATCH;
UPDATE CRM_WorkGuide_Categories SET Is_Deleted=1 WHERE ID=@parent;
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@item,@parent,'view';THROW 51999,'Deleted category accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
UPDATE CRM_WorkGuide_Categories SET Is_Deleted=0 WHERE ID=@parent;
SET @xml=CONVERT(xml,CONCAT('<grants><grant id="',@parent,'" view="1" download="1"/></grants>'));
EXEC CRM_Save_WorkGuide_Permissions 1,@a,@xml,@ver;
SELECT @ver=Row_Version FROM CRM_WorkGuide_AccessState WHERE Account_ID=@a;
EXEC Customer_WorkGuide_File @a,@stamp,@item,@parent,'view';
EXEC Customer_WorkGuide_File @a,@stamp,@item,@parent,'download';
EXEC CRM_Save_WorkGuide_Permissions 1,@a,N'<grants/>',@ver;
BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@item,@parent,'view';THROW 51999,'Revoked permission accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
IF NOT EXISTS(SELECT 1 FROM CRM_Activity_Logs WHERE Account_ID=@a AND Entity=N'WorkGuide_Permissions' AND Before_Data.exist('/row/Permissions/grant')=1 AND After_Data.exist('/row/Permissions/grant')=0) THROW 51999,'Permission before/after audit missing',1;
IF NOT EXISTS(SELECT 1 FROM Customer_Portal_Activity WHERE AccountID=@a AND Action='guide-view' AND After_Data.value('(/row/Category_ID/text())[1]','int')=@parent) THROW 51999,'Category view audit missing',1;
IF NOT EXISTS(SELECT 1 FROM Customer_Portal_Activity WHERE AccountID=@a AND Action='guide-download') THROW 51999,'Download audit missing',1;
DELETE Customer_Portal_Activity WHERE AccountID=@a;DELETE CRM_Activity_Logs WHERE Account_ID=@a;DELETE Customer_Logins WHERE AccountID=@a;
DELETE CRM_WorkGuide_AccessState WHERE Account_ID=@a;
DELETE CRM_WorkGuide_ItemCategories WHERE Item_ID=@item;DELETE CRM_WorkGuide_Items WHERE ID=@item;
DELETE CRM_WorkGuide_Categories WHERE ID=@child;DELETE CRM_WorkGuide_Categories WHERE ID IN(@parent,@second);
DELETE CRM_Accounts WHERE ID IN(@a,@other);
DECLARE @Reseed nvarchar(200)=N'DBCC CHECKIDENT (''dbo.CRM_Accounts'', RESEED, '+CONVERT(nvarchar(40),@AccountSeed)+N') WITH NO_INFOMSGS;';EXEC(@Reseed);
SELECT 'PASS exact-category grants, independent actions, revocation, current identity and audit' Result;
